<?php /** @var \Sysfera\Plugin $sf @var array $list @var string $sub @var string $sort @var string $dir @var string $q @var array $counts */
include __DIR__ . '/_nav.php';
$qs = fn(array $o): string => $sf->url('/invoices?' . http_build_query(array_filter(array_merge(['tab' => $sub, 'sort' => $sort, 'dir' => $dir, 'q' => $q], $o), fn($v) => $v !== '')));
$arrow = fn(string $col): string => $sort === $col ? ($dir === 'asc' ? ' ▲' : ' ▼') : ''; ?>
<div class="page-h"><h1><?= e($sf->t('nav_invoices')) ?></h1></div>
<nav class="ct-tabs"><a class="<?= $sub === 'pay' ? 'on' : '' ?>" href="<?= e($sf->url('/invoices?tab=pay')) ?>"><?= e($sf->t('inv_tab_pay')) ?><?= $counts['pay'] ? ' <b class="ct-n">' . $counts['pay'] . '</b>' : '' ?></a><a class="<?= $sub === 'receive' ? 'on' : '' ?>" href="<?= e($sf->url('/invoices?tab=receive')) ?>"><?= e($sf->t('inv_tab_receive')) ?><?= $counts['receive'] ? ' <b class="ct-n">' . $counts['receive'] . '</b>' : '' ?></a></nav>
<form method="get" action="<?= e($sf->url('/invoices')) ?>" class="ct-filters"><input type="hidden" name="tab" value="<?= e($sub) ?>"><input type="hidden" name="sort" value="<?= e($sort) ?>"><input type="hidden" name="dir" value="<?= e($dir) ?>">
  <input type="search" name="q" value="<?= e($q) ?>" placeholder="<?= e($sf->t('inv_search_ph')) ?>" size="36"><button class="btn"><?= e($sf->t('search')) ?></button><?php if ($q !== ''): ?><a class="btn" href="<?= e($qs(['q' => ''])) ?>"><?= e($sf->t('reset')) ?></a><?php endif; ?></form>
<?php if (!$list): ?><div class="card empty"><p><?= e($sf->t($q !== '' ? 'none_found' : 'inv_none')) ?></p></div><?php else: ?>
<div class="card flush ct-wrap"><table class="ct-tbl"><tr><th><a href="<?= e($qs(['sort' => 'contract', 'dir' => $sort === 'contract' && $dir === 'asc' ? 'desc' : 'asc'])) ?>"><?= e($sf->t('contract')) ?><?= $arrow('contract') ?></a></th><th><a href="<?= e($qs(['sort' => 'date', 'dir' => $sort === 'date' && $dir === 'desc' ? 'asc' : 'desc'])) ?>"><?= e($sf->t('date')) ?><?= $arrow('date') ?></a></th><th><?= e($sf->t('number')) ?></th><th><?= e($sf->t('step')) ?></th><th class="r"><?= e($sf->t('amount')) ?></th><th><?= e($sf->t('status')) ?></th><th></th></tr>
<?php foreach ($list as $i): ?><tr><td><a href="<?= e($sf->url('/view/' . $i['contract_id'])) ?>"><?= e($i['contract_title']) ?></a></td><td><?= e($ctd($i['created_at'])) ?></td><td><a href="<?= e($sf->url('/invoice/' . $i['id'])) ?>"><?= e($i['number']) ?></a></td>
  <td><?= e($i['todo_name'] !== null ? ($i['todo_pos'] + 1) . '. ' . $i['todo_name'] : $sf->t('whole_contract')) ?> <small class="muted">(<?= (int)$i['steps'] ?>)</small></td><td class="r"><b><?= e($ctm($i['amount'])) ?> <?= e($i['currency']) ?></b></td><td><span class="ct-st <?= $ctst($i['status']) ?>"><?= e($sf->t('inv_' . $i['status'])) ?></span></td>
  <td><?php if ($sub === 'pay' && $i['status'] === 'waiting'): ?><form method="post" action="<?= e($sf->url('/i/' . $i['id'] . '/pay')) ?>" class="inline" data-confirm="<?= e($sf->t('confirm_paid')) ?>"><?= csrf_field() ?><input type="hidden" name="back" value="invoices"><button class="btn sm primary"><?= e($sf->t('i_paid')) ?></button></form>
    <?php elseif ($sub === 'receive' && $i['status'] === 'pending'): ?><form method="post" action="<?= e($sf->url('/i/' . $i['id'] . '/confirm')) ?>" class="inline"><?= csrf_field() ?><input type="hidden" name="back" value="invoices?tab=receive"><button class="btn sm primary"><?= e($sf->t('confirm_payment')) ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></table></div><?php endif; ?>
